patch.content:
body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 28px; }
h2 { font-size: 17px; margin: 0 0 8px; }

.result {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 16px;
  overflow-x: auto;
}

table {
  border-collapse: collapse;
  width: 100%;
  font-size: 14px;
}

th, td {
  border-bottom: 1px solid #e4e4e7;
  padding: 6px 10px;
  text-align: left;
}

th {
  background-color: #f4f4f5;
  font-weight: 600;
  white-space: nowrap;
}

td { white-space: nowrap; }

.muted { color: #52525b; font-size: 13px; margin: 8px 0 0; }

.sql-error {
  background-color: #fef2f2;
  border: 1px solid #fecaca;
  border-radius: 8px;
  color: #991b1b;
  padding: 10px 12px;
  font-family: ui-monospace, monospace;
  font-size: 13px;
  white-space: pre-wrap;
}

// Shop.mn-ий өгөгдлийн сан. Энэ файлыг өөрчлөх шаардлагагүй.
// src/queries.js дотор бичсэн бүх query энд ажиллаж, доор хүснэгт болж гарна.

const SCHEMA = `
CREATE TABLE categories (
  id    INTEGER PRIMARY KEY,
  name  TEXT NOT NULL
);

CREATE TABLE products (
  id           INTEGER PRIMARY KEY,
  name         TEXT NOT NULL,
  price        INTEGER NOT NULL,
  stock        INTEGER NOT NULL,
  category_id  INTEGER REFERENCES categories(id)
);

CREATE TABLE customers (
  id    INTEGER PRIMARY KEY,
  name  TEXT NOT NULL,
  city  TEXT NOT NULL
);

CREATE TABLE orders (
  id           INTEGER PRIMARY KEY,
  customer_id  INTEGER REFERENCES customers(id),
  created_at   TEXT NOT NULL
);

CREATE TABLE order_items (
  order_id    INTEGER REFERENCES orders(id),
  product_id  INTEGER REFERENCES products(id),
  quantity    INTEGER NOT NULL
);

INSERT INTO categories (id, name) VALUES
  (1, 'Хувцас'), (2, 'Гутал'), (3, 'Гэр ахуй');

INSERT INTO products (id, name, price, stock, category_id) VALUES
  (1, 'Монгол дээл',   129000, 4,  1),
  (2, 'Малгай',         45000, 12, 1),
  (3, 'Ноосон ороолт',  29000, 30, 1),
  (4, 'Арьсан гутал',   89000, 0,  2),
  (5, 'Өвлийн гутал',  115000, 7,  2),
  (6, 'Гэрийн ширдэг', 250000, 2,  3),
  (7, 'Аяга таваг',     18000, 40, 3);

INSERT INTO customers (id, name, city) VALUES
  (1, 'Батаа',   'Улаанбаатар'),
  (2, 'Сараа',   'Дархан'),
  (3, 'Ганбат',  'Улаанбаатар'),
  (4, 'Оюунаа',  'Эрдэнэт');

INSERT INTO orders (id, customer_id, created_at) VALUES
  (1, 1, '2026-01-12'),
  (2, 2, '2026-01-15'),
  (3, 1, '2026-02-03'),
  (4, 3, '2026-02-11');

INSERT INTO order_items (order_id, product_id, quantity) VALUES
  (1, 1, 1), (1, 2, 2),
  (2, 4, 1),
  (3, 6, 1), (3, 7, 4),
  (4, 2, 1), (4, 3, 3);
`;

const output = document.getElementById("output");

function renderTable(key, title, result) {
  const box = document.createElement("section");
  box.className = "result";
  box.dataset.testid = "result-" + key;

  const heading = document.createElement("h2");
  heading.textContent = title;
  box.append(heading);

  if (result.error) {
    const problem = document.createElement("p");
    problem.className = "sql-error";
    problem.dataset.testid = "error-" + key;
    problem.textContent = result.error;
    box.append(problem);
    output.append(box);
    return;
  }

  if (result.rows.length === 0) {
    const empty = document.createElement("p");
    empty.className = "muted";
    empty.textContent = "Хоосон үр дүн.";
    box.append(empty);
    output.append(box);
    return;
  }

  const table = document.createElement("table");
  const head = document.createElement("tr");
  for (const column of result.columns) {
    const th = document.createElement("th");
    th.textContent = column;
    head.append(th);
  }
  table.append(head);

  for (const row of result.rows) {
    const tr = document.createElement("tr");
    for (const cell of row) {
      const td = document.createElement("td");
      td.textContent = cell === null ? "—" : String(cell);
      tr.append(td);
    }
    table.append(tr);
  }

  box.append(table);

  const note = document.createElement("p");
  note.className = "muted";
  note.dataset.testid = "count-" + key;
  note.textContent = result.rows.length + " мөр";
  box.append(note);

  output.append(box);
}

(async function () {
  const SQL = await initSqlJs({});
  const db = new SQL.Database();
  db.run(SCHEMA);

  window.db = db;
  window.RESULTS = {};

  const queries = window.QUERIES || {};

  for (const key of Object.keys(queries)) {
    const entry = queries[key];
    const sql = typeof entry === "string" ? entry : entry.sql;
    const title = typeof entry === "string" ? key : entry.title;

    let result;
    try {
      const out = db.exec(sql);
      result = out.length === 0
        ? { columns: [], rows: [] }
        : { columns: out[0].columns, rows: out[0].values };
    } catch (problem) {
      result = { error: problem.message, columns: [], rows: [] };
    }

    window.RESULTS[key] = result;
    renderTable(key, title || key, result);
  }

  document.body.dataset.ready = "1";
})();

